entries[51753] = { ["name"] = "Camouflage", ["text"] = "20 FokusSpontanzauber 1 min Abklingzeit\nIhr und Euer Tier geht in einen Camouflagezustand über, in welchem Ihr nicht als Ziel von Distanzangriffen erfassbar seid. Zudem geht Ihr, solang Ihr Euch nicht bewegt, in einen Verstohlenheitszustand über und die Distanz, auf welche feindliche Kreaturen Euch entdecken können, wird verringert.\n\nWährend der Camouflageeffekt aktiv ist, könnt Ihr Fallen legen, jedoch wird jeglicher von Euch oder Eurem Tier verursachter Schaden den Effekt abbrechen. Kann nicht im Kampf verwendet werden. Hält 1 Min. lang an." }
entries[51754] = { ["name"] = "Element-Tamer Dagoda: Frost Channel" }
entries[51755] = { ["name"] = "Camouflage", ["text"] = "Sofort\nIhr und Euer Tier geht in einen Camouflagezustand über, in welchem Ihr nicht als Ziel von Distanzangriffen erfassbar seid. Zudem geht Ihr, solang Ihr Euch nicht bewegt, in einen Verstohlenheitszustand über und die Distanz, auf welche feindliche Kreaturen Euch entdecken können, wird verringert.\n\nWährend der Camouflageeffekt aktiv ist, könnt Ihr Fallen legen, jedoch wird jeglicher von Euch oder Eurem Tier verursachter Schaden den Effekt abbrechen. Kann nicht im Kampf verwendet werden. Hält 1 Min. lang an." }
