entries[51787] = { ["name"] = "Mystischer Blitz", ["text"] = "300 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nZaubert einen mystischen Blitz herbei, der an der Verbindung des Gegners zur materiellen Welt zerrt. Er verursacht dabei 509 to 591 Arkanschaden, erhöht aber 1 Min. lang die kritische Trefferchance des Zieles um 5%.\nKann bis zu 5-mal gestapelt werden." }
entries[51788] = { ["name"] = "Verlorene Seele", ["text"] = "Sofort\nIhr seid zu einer der verlorenen Seelen geworden. Bewegungstempo um 50% verringert. Feinde können 6 Sek. lang nicht angreifen oder Zauber wirken." }
entries[51790] = { ["name"] = "Brandfalle erschaffen", ["text"] = "Unbegrenzte Reichweite\nSofort 5 sek. Abklingzeit\nEine Feuerfalle platzieren, die dem ersten sich nähernden Feind 1 Min. lang insgesamt (Ranged attack power * 0.1 + 1 * 5) Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
